    "auth.consent.patientBody": "Ekwenyere m isonye na ndụmọdụ ahụike n'ịntanetị na My E-Doctor. Aghọtara m na a ga-edobe ozi m n'ime nzuzo ma jiri ya n'ụzọ nchekwa maka nlekọta ahụike. Aghọtara m oke ndụmọdụ n'ịntanetị ma ekwenyekwara m iso ntuziaka onye na-ahụ maka ahụike m.",
