    "auth.consent.doctorBody": "Ekwenyere m inye ndụmọdụ ahụike n'ịntanetị site na My E-Doctor dabere na iwu dị mkpa na ụkpụrụ ọrụ. A na m akwụsi ike ichekwa nzuzo ndị ọrịa ma jikwaa ozi ahụike niile n'ụzọ nchekwa. Aghọtara m oke telemedicine ma m ga-eji ezi mkpebi klinik mgbe m na-enye nlekọta n'elu ikpo okwu a. Ekwenyekwara m na agụla m, aghọtara m, ma kwado Usoro na Ọnọdụ MyE-Doctor.",
