    "auth.consent.patientTitle": "Ìfọwọ́sí Aláìsàn:",
    "auth.consent.patientBody": "Mo fara mọ́ láti kópa nínú ìmọ̀ràn ìṣègùn lórí ayélujára pẹ̀lú My E-Doctor. Mo mọ̀ pé a ó pa ìwífún mi mọ́ ní asiri, a ó sì lò ó ní ààbò fún ìtọju ìlera. Mo mọ̀ àwọn ààlà ìmọ̀ràn lórí ayélujára, mo sì fara mọ́ láti tẹ̀lé ìtọ́sọ́nà oníṣègùn mi.",
    "auth.consent.doctorTitle": "Ìfọwọ́sí àti Àdéhùn Dókítà:",
    "auth.consent.doctorBody": "Mo fara mọ́ láti pèsè ìmọ̀ràn ìṣègùn lórí ayélujára nípasẹ̀ My E-Doctor gẹ́gẹ́ bí òfin tó wà àti ìlànà amọ̀ja. Mo ṣe ìlérí láti pa asiri aláìsàn mọ́ àti láti ṣàkóso gbogbo ìwífún ìlera ní ààbò. Mo mọ̀ àwọn ààlà telemedicine, mo sì máa lo ìdájọ́ iléewosan tó pé nígbà fífi ìtọju hàn lórí pẹpẹ yìí. Mo tún jẹ́rìí pé mo ti ka, mo lóye, mo sì fara mọ́ Àwọn Òfin àti Àwọn Ìpèníjà MyE-Doctor.",
