    "auth.consent.patientTitle": "موافقة المريض:",
    "auth.consent.patientBody": "أوافق على المشاركة في استشارة طبية افتراضية مع My E-Doctor. أفهم أن معلوماتي ستبقى سرية وستُستخدم بشكل آمن لأغراض الرعاية الطبية. أُقر بحدود الاستشارات الافتراضية وأوافق على اتباع تعليمات مقدم الرعاية الصحية الخاص بي.",
    "auth.consent.doctorTitle": "موافقة واتفاق الطبيب:",
    "auth.consent.doctorBody": "أوافق على تقديم استشارات طبية افتراضية عبر My E-Doctor وفقًا للقوانين المعمول بها والمعايير المهنية. وألتزم بالحفاظ على سرية المرضى والتعامل الآمن مع جميع المعلومات الصحية. وأُقر بحدود الطب عن بُعد وسأمارس الحكم السريري المناسب أثناء تقديم الرعاية عبر هذه المنصة. كما أؤكد أنني قرأت وفهمت وأوافق على الشروط والأحكام الخاصة بـ MyE-Doctor.",
