    "auth.consent.doctorBody": "Ich stimme zu, virtuelle medizinische Konsultationen über My E-Doctor gemäß den geltenden Gesetzen und beruflichen Standards anzubieten. Ich verpflichte mich, die Vertraulichkeit der Patienten zu wahren und alle Gesundheitsinformationen sicher zu verarbeiten. Ich erkenne die Grenzen der Telemedizin an und werde bei der Versorgung über diese Plattform angemessenes klinisches Urteilsvermögen anwenden. Ich bestätige außerdem, dass ich die Allgemeinen Geschäftsbedingungen von MyE-Doctor gelesen, verstanden und akzeptiert habe.",
